begin;

create table public.billing_customers (id uuid primary key default gen_random_uuid(), family_id uuid not null unique references public.families(id) on delete cascade, stripe_customer_id text not null unique check (stripe_customer_id ~ '^cus_[A-Za-z0-9]+$'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, stripe_customer_id text not null check (stripe_customer_id ~ '^cus_[A-Za-z0-9]+$'), stripe_subscription_id text not null unique check (stripe_subscription_id ~ '^sub_[A-Za-z0-9]+$'), product_key text not null default 'roots_family' check (product_key ~ '^[a-z][a-z0-9_]{2,79}$'), price_id text not null check (price_id ~ '^price_[A-Za-z0-9]+$'), status text not null check (status in ('incomplete','incomplete_expired','trialing','active','past_due','canceled','unpaid','paused')), current_period_start timestamptz, current_period_end timestamptz, cancel_at_period_end boolean not null default false, ended_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (current_period_end is null or current_period_start is null or current_period_end >= current_period_start));
create unique index subscriptions_one_current_family_idx on public.subscriptions(family_id) where status in ('trialing','active','past_due','unpaid','paused');
create index subscriptions_customer_idx on public.subscriptions(stripe_customer_id, updated_at desc);
create table public.subscription_events (id uuid primary key default gen_random_uuid(), stripe_event_id text not null unique check (stripe_event_id ~ '^evt_[A-Za-z0-9]+$'), event_type text not null check (char_length(event_type) between 3 and 120), payload jsonb not null check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 1000000), processed_at timestamptz not null default now(), created_at timestamptz not null default now());
create index subscription_events_type_created_idx on public.subscription_events(event_type, created_at desc);
alter table public.billing_customers enable row level security;
alter table public.billing_customers force row level security;
alter table public.subscriptions enable row level security;
alter table public.subscriptions force row level security;
alter table public.subscription_events enable row level security;
alter table public.subscription_events force row level security;
revoke all on public.billing_customers, public.subscriptions, public.subscription_events from public, anon, authenticated;
grant all on public.billing_customers, public.subscriptions, public.subscription_events to service_role;
create trigger billing_customers_set_updated_at before update on public.billing_customers for each row execute function public.set_updated_at();
create trigger subscriptions_set_updated_at before update on public.subscriptions for each row execute function public.set_updated_at();

create or replace function kinavela_private.family_has_entitlement(p_family_id uuid, p_entitlement text) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.subscriptions subscription where subscription.family_id = p_family_id and subscription.status in ('trialing','active','past_due','unpaid','paused') and subscription.product_key = 'roots_family' and p_entitlement in ('roots_stories_ai','extended_archive','advanced_passport','premium_journeys','annual_export')) $$;
create or replace function public.get_my_entitlements() returns table (plan text,status text,has_billing_customer boolean,roots_stories_ai boolean,extended_archive boolean,advanced_passport boolean,premium_journeys boolean,annual_export boolean,current_period_end timestamptz) language sql stable security definer set search_path = '' as $$ with my_family as (select member.family_id from public.family_members member join public.profiles profile on profile.id = member.profile_id where profile.auth_user_id = auth.uid() and profile.status = 'active' and member.status = 'active' and member.role in ('owner','guardian') order by member.created_at limit 1), current_subscription as (select subscription.* from public.subscriptions subscription join my_family family on family.family_id = subscription.family_id where subscription.status in ('trialing','active','past_due','unpaid','paused') order by subscription.updated_at desc limit 1) select coalesce(subscription.product_key,'free'),coalesce(subscription.status,'free'),exists (select 1 from public.billing_customers customer join my_family family on family.family_id = customer.family_id),coalesce(subscription.product_key = 'roots_family',false),coalesce(subscription.product_key = 'roots_family',false),coalesce(subscription.product_key = 'roots_family',false),coalesce(subscription.product_key = 'roots_family',false),coalesce(subscription.product_key = 'roots_family',false),subscription.current_period_end from current_subscription subscription union all select 'free','free',exists (select 1 from public.billing_customers customer join my_family family on family.family_id = customer.family_id),false,false,false,false,false,null::timestamptz where not exists (select 1 from current_subscription) limit 1 $$;
create or replace function public.sync_billing_subscription(p_family_id uuid,p_stripe_customer_id text,p_stripe_subscription_id text,p_product_key text,p_price_id text,p_status text,p_current_period_start timestamptz default null,p_current_period_end timestamptz default null,p_cancel_at_period_end boolean default false,p_ended_at timestamptz default null) returns boolean language plpgsql security definer set search_path = '' as $$ begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role_required'; end if; if p_status not in ('incomplete','incomplete_expired','trialing','active','past_due','canceled','unpaid','paused') then raise exception 'invalid_subscription_status'; end if; if not exists (select 1 from public.families where id = p_family_id) then raise exception 'family_not_found'; end if; if p_status in ('trialing','active','past_due','unpaid','paused') then update public.subscriptions set status = 'canceled',ended_at = coalesce(ended_at,now()),updated_at = now() where family_id = p_family_id and status in ('trialing','active','past_due','unpaid','paused') and stripe_subscription_id <> p_stripe_subscription_id; end if; insert into public.billing_customers(family_id,stripe_customer_id) values (p_family_id,p_stripe_customer_id) on conflict (family_id) do update set stripe_customer_id = excluded.stripe_customer_id,updated_at = now(); insert into public.subscriptions(family_id,stripe_customer_id,stripe_subscription_id,product_key,price_id,status,current_period_start,current_period_end,cancel_at_period_end,ended_at) values (p_family_id,p_stripe_customer_id,p_stripe_subscription_id,coalesce(p_product_key,'roots_family'),p_price_id,p_status,p_current_period_start,p_current_period_end,coalesce(p_cancel_at_period_end,false),p_ended_at) on conflict (stripe_subscription_id) do update set family_id = excluded.family_id,stripe_customer_id = excluded.stripe_customer_id,product_key = excluded.product_key,price_id = excluded.price_id,status = excluded.status,current_period_start = excluded.current_period_start,current_period_end = excluded.current_period_end,cancel_at_period_end = excluded.cancel_at_period_end,ended_at = excluded.ended_at,updated_at = now(); insert into public.audit_events(actor_profile_id,event_type,entity_type,metadata) values (null,'subscription_synced','subscription',jsonb_build_object('family_id',p_family_id,'status',p_status)); return true; end; $$;
create or replace function public.record_subscription_event(p_stripe_event_id text,p_event_type text,p_payload jsonb) returns boolean language plpgsql security definer set search_path = '' as $$ begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role_required'; end if; insert into public.subscription_events(stripe_event_id,event_type,payload) values (p_stripe_event_id,p_event_type,p_payload) on conflict (stripe_event_id) do nothing; return found; end; $$;
revoke all on function kinavela_private.family_has_entitlement(uuid,text) from public,anon,authenticated,service_role;
revoke all on function public.get_my_entitlements(),public.sync_billing_subscription(uuid,text,text,text,text,text,timestamptz,timestamptz,boolean,timestamptz),public.record_subscription_event(text,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.get_my_entitlements() to authenticated;
grant execute on function public.sync_billing_subscription(uuid,text,text,text,text,text,timestamptz,timestamptz,boolean,timestamptz),public.record_subscription_event(text,text,jsonb) to service_role;
insert into kinavela_private.admin_feature_flags(flag_key,enabled,rollout_percent,description) values ('premium_billing',false,0,'Stripe premium billing and entitlements') on conflict (flag_key) do nothing;
insert into kinavela_private.schema_migrations(version) values ('202608110010_billing') on conflict (version) do nothing;
notify pgrst, 'reload schema';
commit;
